S = "Hakeem Force Academy"
QS = [
(S, "In which part of the world is the Gobi Desert located?", ["Mongolia and northern China", "Central Africa", "Southern Australia", "Arabian Peninsula"], 0, "The Gobi is a large cold desert in East Asia. It covers parts of southern Mongolia and northern China.", "The Gobi is known for fossil finds, including dinosaur eggs.", [3559]),
(S, "Which nation, associated with the city of Iram in the Quran, was destroyed after rejecting Hazrat Hud (AS)?", ["Thamud", "Aad", "People of Madyan", "People of Lut"], 1, "The people of Aad, who lived in Iram of the pillars, rejected Hazrat Hud (AS). They were destroyed by a violent windstorm.", "The people of Thamud were the nation of Hazrat Saleh (AS).", [1962, 3861]),
(S, "What is the determinant of a non-square matrix?", ["Zero", "One", "Not defined", "Equal to its number of rows"], 2, "A determinant can be found only for a square matrix, with equal rows and columns. For a non-square matrix it does not exist.", "A square matrix with determinant zero is called a singular matrix.", [2875]),
(S, "Where is the Kot Diji fort located, in terms of district?", ["Khairpur", "Larkana", "Sukkur", "Hyderabad"], 0, "Kot Diji is a town in Khairpur district of Sindh. Its fort was built by the Talpur rulers.", "Kot Diji is also an important pre-Harappan archaeological site.", [774]),
(S, "In which province of Pakistan is Kot Diji located?", ["Punjab", "Balochistan", "Khyber Pakhtunkhwa", "Sindh"], 3, "Kot Diji lies in Khairpur district in the province of Sindh.", "The Kot Diji culture is dated before the Indus Valley Civilization.", [18, 3540, 1100]),
(S, "In which district of Punjab is Harappa located?", ["Multan", "Bahawalpur", "Sahiwal", "Sargodha"], 2, "The ruins of Harappa lie near the Ravi River in Sahiwal district, Punjab.", "Harappa was first excavated in the 1920s.", [773, 2035]),
(S, "In which year did Liaquat Ali Khan, the first Prime Minister of Pakistan, die?", ["1948", "1949", "1951", "1958"], 2, "Liaquat Ali Khan was assassinated on 16 October 1951 at Company Bagh in Rawalpindi.", "Company Bagh was later renamed Liaquat Bagh.", [416]),
(S, "In which year did Nawab Waqar-ul-Mulk die?", ["1906", "1917", "1930", "1947"], 1, "Nawab Waqar-ul-Mulk (Mushtaq Hussain) died in January 1917.", "He was a founding member of the All India Muslim League in 1906.", [2127]),
(S, "Fill in the blank: His mother died ___ cancer.", ["with", "at", "of", "by"], 2, "The correct preposition with 'died' for a disease is 'of'. We say 'died of cancer'.", "We say 'died from' an injury and 'died in' an accident or war.", [1590, 2278]),
(S, "What is the common difference in the series 2, 6, 10, 14?", ["2", "3", "4", "6"], 2, "6 - 2 = 4, 10 - 6 = 4 and 14 - 10 = 4. So the difference is 4.", "A series with a constant difference is called an arithmetic progression.", [2879]),
(S, "What is the common difference in the series 4, 8, 12, 16?", ["3", "4", "5", "8"], 1, "8 - 4 = 4, 12 - 8 = 4 and 16 - 12 = 4. So the difference is 4.", "The next term in this series is 20.", [285]),
(S, "What is the common difference in the numbers of the series A4, B8, C12?", ["2", "3", "4", "8"], 2, "The numbers are 4, 8, 12 and the letters go A, B, C. The number difference is 8 - 4 = 4 and 12 - 8 = 4.", "The next term would be D16.", [2880]),
(S, "Which term is different in this series: A3, C5, E7, G9, I12?", ["C5", "E7", "G9", "I12"], 3, "Letters move by 2 (A, C, E, G, I) and numbers also move by 2 (3, 5, 7, 9, 11). The last term should be I11, so I12 is wrong.", "Such questions test both letter and number patterns together.", [3773]),
(S, "Sidra is 5 years old and her brother is twice her age. How old is her brother?", ["7 years", "10 years", "12 years", "15 years"], 1, "Twice her age is 2 x 5 = 10 years. So the brother is 10 years old.", "The age difference between them is 5 years.", [2392]),
(S, "Which of the following is a three-dimensional shape?", ["Square", "Triangle", "Circle", "Cube"], 3, "A cube has length, width and height, so it is three-dimensional. Square, triangle and circle are flat two-dimensional shapes.", "A cube has 6 faces, 12 edges and 8 vertices.", [3766, 3899]),
(S, "Who discovered micro-organisms (microscopic life)?", ["Louis Pasteur", "Robert Koch", "Antonie van Leeuwenhoek", "Alexander Fleming"], 2, "Antonie van Leeuwenhoek first observed bacteria and other tiny organisms with his own microscopes in the 1670s.", "He is often called the father of microbiology.", [1195, 4105]),
(S, "Which of these antonyms is opposite in meaning to 'disgusting'?", ["Delightful", "Repulsive", "Foul", "Horrible"], 0, "Disgusting means very unpleasant. Delightful is the opposite, meaning very pleasant.", "Repulsive and foul are synonyms of disgusting.", [924]),
(S, "Which word is closest in meaning to 'disgusting'?", ["Charming", "Revolting", "Gentle", "Cheerful"], 1, "Disgusting means causing strong dislike or sickness. Revolting has nearly the same meaning.", "Other synonyms are repulsive, nasty and foul.", [1025]),
(S, "What is the antonym of 'dishonest'?", ["Honest", "Cunning", "Deceitful", "Crooked"], 0, "Dishonest means not truthful. Honest is its opposite.", "The prefix dis- often makes the opposite meaning.", [2757]),
(S, "Which word is closest in meaning to 'dishonest'?", ["Sincere", "Truthful", "Deceitful", "Loyal"], 2, "Dishonest means untruthful or cheating. Deceitful has the same sense.", "Fraudulent is another synonym of dishonest.", [3056]),
(S, "Which word is a synonym of 'disruption'?", ["Calm", "Order", "Disturbance", "Progress"], 2, "Disruption means a break or interruption in the normal course of something. Disturbance has the same meaning.", "The opposite of disruption is continuity.", [944, 39]),
(S, "In which year was the 1956 Constitution of Pakistan abrogated?", ["1957", "1958", "1962", "1969"], 1, "President Iskander Mirza abrogated the 1956 Constitution on 7 October 1958 and imposed martial law.", "The 1956 Constitution had been in force since 23 March 1956.", [2170]),
(S, "Which group of vitamins does not dissolve in water?", ["B and C", "A, D, E and K", "B1 and B2", "Only C"], 1, "Vitamins A, D, E and K are fat-soluble. They dissolve in fat and not in water.", "Vitamins B-complex and C are water-soluble.", [1187]),
(S, "What is the distance between the points (4, 0) and (3, 0)?", ["0", "1", "3", "7"], 1, "Both points are on the x-axis, so the distance is the difference of x values: 4 - 3 = 1.", "The distance formula is the square root of the sum of squared differences.", [2883]),
(S, "In which division of Balochistan is Gwadar located?", ["Quetta", "Makran", "Kalat", "Zhob"], 1, "Gwadar district is part of Makran Division in southwestern Balochistan.", "Makran division also includes Kech (Turbat) and Panjgur districts.", [2039, 2040]),
(S, "In which district of Balochistan is the Gwadar port located?", ["Gwadar", "Lasbela", "Kech", "Awaran"], 0, "The port lies in Gwadar district, whose headquarters is Gwadar city.", "Gwadar was bought from Oman in 1958.", [2034]),
(S, "Which is the largest district of Balochistan by area?", ["Kech", "Khuzdar", "Chagai", "Quetta"], 2, "Chagai district is the largest by area in Balochistan. It covers about 50,000 square km.", "Some sources give Kharan as close in size, so sources can differ slightly.", [3804]),
(S, "How many districts does Punjab (Pakistan) have at present?", ["36", "38", "41", "45"], 2, "Punjab has 41 districts grouped into 10 divisions. A claim of 45 districts was officially rejected.", "Earlier counts were 36 and then 40 before the newer districts were added.", [710]),
(S, "Fill in the blank with the correct preposition: The doctor gives him medicine ___ his cough.", ["for", "at", "on", "with"], 0, "We use 'for' to show the purpose or the illness being treated. So it is 'medicine for his cough'.", "We also say 'a cure for' a disease.", [1559]),
(S, "Which document served as the basis for the 1973 Constitution of Pakistan?", ["Objective Resolution", "Independence Act", "Government of India Act 1935", "Simla Agreement"], 0, "The Objective Resolution of 1949 became the preamble and guiding basis of the constitutions of Pakistan, including 1973.", "It was made a substantive part of the constitution by Article 2-A in 1985.", [1138]),
(S, "Horse is to mare as dog is to what?", ["Puppy", "Bitch", "Cub", "Vixen"], 1, "A mare is a female horse. The female dog is called a bitch.", "A young dog is a puppy.", [1668]),
(S, "What is the domain of the function tan x?", ["All real numbers", "All real numbers except odd multiples of pi/2", "All real numbers except multiples of pi", "Only positive real numbers"], 1, "tan x = sin x / cos x, which is undefined where cos x = 0. That happens at odd multiples of pi/2.", "The range of tan x is all real numbers.", [2885]),
(S, "Article 25-A of the Constitution of Pakistan deals with which right?", ["Right to education", "Right to property", "Freedom of speech", "Right to vote"], 0, "Article 25-A, added by the 18th Amendment in 2010, gives free and compulsory education to children aged 5 to 16.", "The 18th Amendment was passed in April 2010.", [761]),
]
